Testing your bot > Unit tests with a scripted model

`chatcops test` checks what a real model says. For code around the bot, such as your tools, a custom store or a page that reads the stream, a model is slow and never answers the same way twice. `@chatcops/core/testing` has a provider that plays back a script instead:

```typescript
import { expect, it } from 'vitest';
import { scriptedProvider, textStep, toolStep } from '@chatcops/core/testing';
import { chatcopsVercelHandler } from '@chatcops/server/vercel';

it('looks the order up before answering', async () => {
  const lookups: unknown[] = [];
  const provider = scriptedProvider([
    toolStep([{ name: 'lookup_order', input: { id: 'A-1' } }]),
    textStep('Your order shipped on Monday.'),
  ]);
  const handler = chatcopsVercelHandler({
    provider,
    systemPrompt: 'You answer questions about orders.',
    tools: [{
      name: 'lookup_order',
      description: 'Finds an order by id.',
      inputSchema: { type: 'object', properties: { id: { type: 'string' } }, required: ['id'] },
      async execute(input) {
        lookups.push(input);
        return { success: true, data: { shipped: 'Monday' } };
      },
    }],
  });

  const response = await handler(new Request('http://localhost/api/chat', {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ protocol: 1, conversationId: 'test-1', message: 'Where is order A-1?' }),
  }));

  // The reply is a stream of `data:` lines, one part each.
  const parts = (await response.text())
    .split('\n')
    .filter((line) => line.startsWith('data: {'))
    .map((line) => JSON.parse(line.slice(6)));
  const reply = parts.filter((part) => part.type === 'text-delta').map((part) => part.delta).join('');

  expect(reply).toBe('Your order shipped on Monday.');
  expect(lookups).toEqual([{ id: 'A-1' }]);
  expect(provider.calls).toHaveLength(2); // the second step saw the tool's result
});
```

